import {riskTypes,riskLevels,riskStatuses,riskSummary,riskIsActive} from './risks.mjs';
import {cases,estimate,costBreakdown,teamEffort,validateResources,sourceTypes,safeSourceUrl} from './resources.mjs';
const $=id=>document.getElementById(id);
const n=(v,d=0)=>new Intl.NumberFormat('nb-NO',{maximumFractionDigits:d}).format(v);
const kr=v=>n(v)+' kr';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const labels={low:'Lav',expected:'Forventet',high:'Høy'};
function input(label,field,value,{type='number',max,step='any',disabled=false}={}){return `<label>${label}<input data-field="${field}" type="${type}" value="${esc(value)}" ${type==='number'?`min="0" step="${step}" ${max?`max="${max}"`:''}`:'maxlength="120"'} ${disabled?'disabled':''} required></label>`;}
function triple(field,value,disabled=false){return `<div class="estimate-triple">${cases.map(k=>input(labels[k],field?`${field}.${k}`:k,value[k],{disabled:disabled&&k!=='expected'})).join('')}</div>`;}
const interval=e=>`${n(e.low,2)} / <strong>${n(e.expected,2)}</strong> / ${n(e.high,2)}`;
export function renderResourceDetails(t){
 renderSources(t);renderRisks(t);
 const b=costBreakdown(t),low=costBreakdown(t,'low'),high=costBreakdown(t,'high');
 $('resource-summary').innerHTML=[['Øvrige kostnader',kr(b.annual+b.once),'Tjenester, drift og etablering'],['Teamkostnad',kr(b.labor),'Inkludert i nettoverdi'],['Arbeidsinnsats',n(b.effort,1)+' ressursuker',`${n(low.effort,1)}–${n(high.effort,1)} ressursuker · lav–høy`],['Ferdig etter',t.teams?.length?n(b.duration,1)+' uker':'Ikke estimert',t.teams?.length?`${n(low.duration,1)}–${n(high.duration,1)} uker · fra felles start`:'Legg til team og varighet']].map(([label,value,note])=>`<div><span>${label}</span><strong>${value}</strong><small>${note}</small></div>`).join('');
 const costRows=t.costItems??[];
 $('cost-detail-rows').innerHTML=costRows.map(r=>`<tr><th scope="row">${esc(r.name)}<small>${r.kind==='annual'?'Årlig':'Engang'} · ${r.basis==='known'?'Kjent tall':'Anslag'}</small>${r.note?`<small>${esc(r.note)}</small>`:''}<small>${sourceReference(t,r.sourceId)}</small></th>${cases.map(k=>`<td>${kr(r[k])}</td>`).join('')}</tr>`).join('')+`<tr><th scope="row">Teaminnsats<small>Kun team merket «Inkluder kostnad»</small></th>${cases.map(k=>`<td>${kr(costBreakdown(t,k).labor)}</td>`).join('')}</tr><tr class="total-row"><th scope="row">Total økonomisk kostnad</th>${cases.map(k=>`<td>${kr(costBreakdown(t,k).total)}</td>`).join('')}</tr>`;
 const max=Math.max(high.total,1);$('cost-bars').innerHTML=cases.map(k=>{const c=costBreakdown(t,k);return `<div class="cost-bar-row"><span>${labels[k]}</span><div class="cost-bar" role="img" aria-label="${labels[k]} kostnad: årlig ${kr(c.annual)}, engang ${kr(c.once)}, team ${kr(c.labor)}">${[['annual',c.annual],['once',c.once],['labor',c.labor]].map(([kind,value])=>`<span class="cost-${kind}" style="width:${value/max*100}%"></span>`).join('')}</div><strong>${kr(c.total)}</strong></div>`}).join('');
 $('team-detail-rows').innerHTML=(t.teams??[]).length?t.teams.map(r=>`<tr><th scope="row">${esc(r.name)}<small>${esc(r.role||'Ingen oppgave angitt')}</small><small>${r.includeCost?'Kostnad inkludert':'Kostnad utelatt'} · ${kr(r.rate)} / fulltidsuke</small>${r.note?`<small>${esc(r.note)}</small>`:''}<small>${sourceReference(t,r.sourceId)}</small></th><td>${interval(r.fte)}</td><td>${interval(r.weeks)}</td><td>${cases.map(k=>n(teamEffort(r,k),1)).join(' / ')}</td></tr>`).join(''):'<tr><td colspan="4">Ingen team er lagt til. Ressursbehov er ikke estimert.</td></tr>';
 $('team-timeline').innerHTML=(t.teams??[]).map(r=>`<div class="timeline-row"><div><strong>${esc(r.name)}</strong><small>Oppstart etter ${n(r.start,1)} uker · ferdig uke ${n(r.start+r.weeks.expected,1)}</small></div><div class="timeline-track" role="img" aria-label="${esc(r.name)}: start etter ${n(r.start)} uker, varighet lav ${n(r.weeks.low)}, forventet ${n(r.weeks.expected)}, høy ${n(r.weeks.high)} uker"><span class="timeline-high" style="left:${r.start/52*100}%;width:${r.weeks.high/52*100}%"></span><span class="timeline-expected" style="left:${r.start/52*100}%;width:${r.weeks.expected/52*100}%"></span><span class="timeline-low" style="left:${r.start/52*100}%;width:${r.weeks.low/52*100}%"></span></div></div>`).join('');
}
function costCard(r,i,sources){return `<fieldset class="resource-card" data-cost-id="${esc(r.id)}"><legend>Kostnadspost ${i+1}</legend><button class="remove-row" type="button" data-remove-cost="${esc(r.id)}" aria-label="Fjern kostnadspost ${i+1}">Fjern</button><div class="form-grid">${input('Hva betaler vi for?','name',r.name,{type:'text'})}<label>Kostnadstype<select data-field="kind"><option value="annual" ${r.kind==='annual'?'selected':''}>Årlig kostnad (12 måneder)</option><option value="once" ${r.kind==='once'?'selected':''}>Engangskostnad (første år)</option></select></label></div><label>Grunnlag<select data-field="basis"><option value="estimate" ${r.basis==='estimate'?'selected':''}>Anslag — lav / forventet / høy</option><option value="known" ${r.basis==='known'?'selected':''}>Kjent tall — samme beløp i alle scenarioer</option></select></label><div class="field-title">Beløp i kroner${r.kind==='annual'?' per 12 måneder':''}</div>${triple('',r,r.basis==='known')}${sourceSelect(sources,r.sourceId)}<label>Fordeling eller forutsetning<textarea data-field="note" rows="2" maxlength="600">${esc(r.note)}</textarea></label></fieldset>`;}
function teamCard(r,i,sources){return `<fieldset class="resource-card" data-team-id="${esc(r.id)}"><legend>Team ${i+1}</legend><button class="remove-row" type="button" data-remove-team="${esc(r.id)}" aria-label="Fjern team ${i+1}">Fjern</button><div class="form-grid">${input('Teamnavn','name',r.name,{type:'text'})}<label>Oppgave / leveranse<input data-field="role" value="${esc(r.role)}" maxlength="160"></label></div><div class="field-title">Bemanning (fulltidsekvivalenter)</div><p class="field-help">1 = én fulltidsressurs. To personer på 50 % = 1.</p>${triple('fte',r.fte)}<div class="field-title">Varighet (uker)</div>${triple('weeks',r.weeks)}<div class="form-grid">${input('Oppstart etter (uker)','start',r.start,{max:52})}${input('Kostnad per fulltidsuke (kr)','rate',r.rate)}</div><label class="checkbox-label"><input type="checkbox" data-field="includeCost" ${r.includeCost?'checked':''}> Inkluder teamkostnaden i nettoverdi</label>${sourceSelect(sources,r.sourceId)}<label>Avhengigheter og forutsetninger<textarea data-field="note" rows="2" maxlength="600">${esc(r.note)}</textarea></label><p class="team-preview"></p></fieldset>`;}
export function renderResourceEditor(t){
 $('risk-editor-rows').innerHTML=(t.risks??[]).map((r,i)=>riskCard(r,i,t.sources??[])).join('')||'<p class="empty-editor">Ingen risikoer eller avhengigheter er registrert. Det betyr ikke at tiltaket er risikofritt.</p>';
 $('source-editor-rows').innerHTML=(t.sources??[]).map(sourceCard).join('')||'<p class="empty-editor">Ingen kildereferanser. Legg til en lenke eller navnet på et internt dokument.</p>';
 $('effect-source').innerHTML=sourceOptions(t.sources??[],t.effectSourceId);
 const rows=t.costItems??[{id:crypto.randomUUID(),name:'Årlig tiltakskostnad',kind:'annual',basis:'known',...estimate(t.cost??0),note:''},{id:crypto.randomUUID(),name:'Engangskostnad',kind:'once',basis:'known',...estimate(t.setup??0),note:''}];
 $('cost-editor-rows').innerHTML=rows.length?rows.map((r,i)=>costCard(r,i,t.sources??[])).join(''):'<p class="empty-editor">Ingen øvrige kostnadsposter. Legg til tjeneste, lisens, utstyr eller etablering.</p>';
 $('team-editor-rows').innerHTML=t.teams?.length?t.teams.map((r,i)=>teamCard(r,i,t.sources??[])).join(''):'<p class="empty-editor">Ingen team ennå. Legg til teamene som må bidra.</p>';
 updatePreview();
 $('form').dispatchEvent(new Event('editor-rows-rendered'));
}
function getFields(card){const out={};card.querySelectorAll('[data-field]').forEach(el=>{const path=el.dataset.field.split('.');const value=el.type==='checkbox'?el.checked:el.type==='number'?(el.value.trim()===''?NaN:Number(el.value)):el.value;if(path.length===2){out[path[0]]??={};out[path[0]][path[1]]=value}else out[path[0]]=value});return out;}
export function readResourceEditor(){return {risks:[...document.querySelectorAll('[data-risk-id]')].map(el=>({id:el.dataset.riskId,...getFields(el)})),sources:[...document.querySelectorAll('[data-source-id]')].map(el=>({id:el.dataset.sourceId,...getFields(el)})),effectSourceId:$('effect-source').value,costItems:[...document.querySelectorAll('[data-cost-id]')].map(el=>({id:el.dataset.costId,...getFields(el)})),teams:[...document.querySelectorAll('[data-team-id]')].map(el=>({id:el.dataset.teamId,...getFields(el)}))};}
function updatePreview(){
 const t=readResourceEditor();const error=validateResources(t);
 $('draft-resources').textContent=error?'Fyll ut gyldige anslag for å se totalen.':`Forventet: ${kr(costBreakdown(t).total)} totalt · ${n(costBreakdown(t).effort,1)} ressursuker · ${t.teams.length?n(costBreakdown(t).duration,1)+' uker til ferdig':'varighet ikke estimert'}`;
 document.querySelectorAll('[data-team-id]').forEach(el=>{const r=getFields(el);const effort=teamEffort(r);el.querySelector('.team-preview').textContent=Number.isFinite(effort*r.rate)?`Forventet innsats: ${n(effort,1)} ressursuker · ${kr(effort*r.rate)}${r.includeCost?' i økonomisk kostnad':' (utelatt fra nettoverdi)'}`:'Fyll ut bemanning, varighet og ukesats.';});
}
export function bindResourceEditor(){
 $('form').addEventListener('change',e=>{const card=e.target.closest('[data-risk-id]');if(card&&e.target.dataset.field==='kind'){const t=readResourceEditor();const r=t.risks.find(r=>r.id===card.dataset.riskId);r.status=Object.keys(riskStatuses[r.kind])[0];renderResourceEditor(t);document.querySelector(`[data-risk-id="${r.id}"] [data-field="kind"]`).focus()}});
 $('form').addEventListener('input',e=>{const card=e.target.closest('[data-cost-id]');if(card&&card.querySelector('[data-field="basis"]').value==='known'){const v=card.querySelector('[data-field="expected"]').value;for(const k of ['low','high'])card.querySelector(`[data-field="${k}"]`).value=v;}if(e.target.closest('[data-source-id]'))refreshSourceSelects();updatePreview()});
 $('resource-editor-section').addEventListener('change',e=>{const card=e.target.closest('[data-cost-id]');if(card&&e.target.dataset.field==='basis'){const known=e.target.value==='known';for(const k of ['low','high']){const input=card.querySelector(`[data-field="${k}"]`);input.disabled=known;if(known)input.value=card.querySelector('[data-field="expected"]').value;}updatePreview();}});
 $('form').addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const t=readResourceEditor();let focusId=null;
 if(b.id==='add-risk'){const id=crypto.randomUUID();t.risks.push({id,title:'',kind:'risk',status:'open',probability:'medium',severity:'medium',consequence:'',owner:'',action:'',trigger:'',sourceId:''});focusId=`[data-risk-id="${id}"] input`}
 else if(b.dataset.removeRisk)t.risks=t.risks.filter(r=>r.id!==b.dataset.removeRisk);
 else if(b.id==='add-source'){const id=crypto.randomUUID();t.sources.push({id,title:'',url:'',version:'',type:'internal',note:''});focusId=`[data-source-id="${id}"] input`}
 else if(b.dataset.removeSource){t.sources=t.sources.filter(r=>r.id!==b.dataset.removeSource);if(t.effectSourceId===b.dataset.removeSource)t.effectSourceId='';for(const row of [...t.costItems,...t.teams,...t.risks])if(row.sourceId===b.dataset.removeSource)row.sourceId='';}
 else if(b.id==='add-cost'){const id=crypto.randomUUID();t.costItems.push({id,name:'',kind:'annual',basis:'estimate',...estimate(),note:''});focusId=`[data-cost-id="${id}"] input`}
 else if(b.id==='add-team'){const id=crypto.randomUUID();t.teams.push({id,name:'',role:'',fte:estimate(.5,1,1.5),weeks:estimate(2,4,8),start:0,rate:30000,includeCost:true,note:''});focusId=`[data-team-id="${id}"] input`}
 else if(b.dataset.removeCost)t.costItems=t.costItems.filter(r=>r.id!==b.dataset.removeCost);
 else if(b.dataset.removeTeam)t.teams=t.teams.filter(r=>r.id!==b.dataset.removeTeam);
 else return;
 renderResourceEditor(t);if(focusId)document.querySelector(focusId)?.focus();else $(b.dataset.removeRisk?'add-risk':b.dataset.removeSource?'add-source':b.dataset.removeCost?'add-cost':'add-team').focus();
 });
}

function sourceOptions(sources,id=''){return '<option value="">Ingen kilde valgt</option>'+sources.map((s,i)=>`<option value="${esc(s.id)}" ${id===s.id?'selected':''}>${esc(s.title||'Ny kilde '+(i+1))}</option>`).join('')}
function sourceSelect(sources,id){return `<label>Kildereferanse<select data-field="sourceId">${sourceOptions(sources,id)}</select></label>`}
function sourceCard(s,i){return `<fieldset class="resource-card" data-source-id="${esc(s.id)}"><legend>Kilde ${i+1}</legend><button type="button" class="remove-row" data-remove-source="${esc(s.id)}" aria-label="Fjern kilde ${i+1}">Fjern</button><div class="form-grid">${input('Tittel / dokumentnavn','title',s.title,{type:'text'})}<label>Kildetype<select data-field="type">${Object.entries(sourceTypes).map(([k,v])=>`<option value="${k}" ${s.type===k?'selected':''}>${v}</option>`).join('')}</select></label></div><label>Lenke (valgfritt)<input type="url" data-field="url" value="${esc(s.url)}" placeholder="https://…" maxlength="2000"></label><label>Dato / versjon<input data-field="version" value="${esc(s.version)}" placeholder="F.eks. tilbud 23.09.2026, versjon 2" maxlength="120"></label><label>Hva støtter kilden? Side, avsnitt og forbehold<textarea data-field="note" rows="2" maxlength="1000">${esc(s.note)}</textarea></label></fieldset>`}
function refreshSourceSelects(){const sources=readResourceEditor().sources;document.querySelectorAll('[data-field="sourceId"],#effect-source').forEach(el=>{const selected=el.value;el.innerHTML=sourceOptions(sources,selected)})}
export function sourceReference(t,id){const s=(t.sources??[]).find(s=>s.id===id);if(!s)return '<span class="missing-source">Ingen kilde knyttet til anslaget</span>';return `<a class="source-ref" href="#ref-${esc(s.id)}">Kilde: ${esc(s.title)}</a>`}
function renderSources(t){const sources=t.sources??[];$('source-count').textContent=sources.length+' kilder';$('source-list').innerHTML=sources.length?sources.map(s=>{const url=safeSourceUrl(s.url);return `<article id="ref-${esc(s.id)}" class="source-entry"><span class="badge neutral">${sourceTypes[s.type]}</span><h4>${url?`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(s.title)} ↗</a>`:esc(s.title)}</h4>${s.version?`<p>${esc(s.version)}</p>`:''}<p>${esc(s.note||'Ingen kildenotat registrert.')}</p>${url?`<small>${esc(url)}</small>`:'<small>Dokumentreferanse uten lenke</small>'}</article>`}).join(''):'<p class="resource-note">Ingen kildereferanser er lagt til for dette tiltaket. Eksempeldataene er illustrative.</p>'}

function choice(label,field,value,options,disabled=false){return `<label>${label}<select data-field="${field}" ${disabled?'disabled':''}>${Object.entries(options).map(([k,v])=>`<option value="${k}" ${value===k?'selected':''}>${v}</option>`).join('')}</select></label>`}
function riskCard(r,i,sources){return `<fieldset class="resource-card" data-risk-id="${esc(r.id)}"><legend>Forhold ${i+1}</legend><button type="button" class="remove-row" data-remove-risk="${esc(r.id)}" aria-label="Fjern forhold ${i+1}">Fjern</button>${input('Hva må være på plass / hva kan gå galt?','title',r.title,{type:'text'})}<div class="form-grid">${choice('Type','kind',r.kind,riskTypes)}${choice('Status','status',r.status,riskStatuses[r.kind])}${choice('Sannsynlighet','probability',r.probability,riskLevels,r.kind==='dependency')}${choice('Konsekvensgrad','severity',r.severity,riskLevels)}</div><label>Konsekvens for verdi, kostnad eller tid<textarea data-field="consequence" rows="2" maxlength="1000" required>${esc(r.consequence)}</textarea></label><label>Ansvarlig team / person<input data-field="owner" value="${esc(r.owner)}" maxlength="120" placeholder="Hvem følger opp?"></label><label>Hva gjør vi med det?<textarea data-field="action" rows="2" maxlength="1000">${esc(r.action)}</textarea></label><label>Varselsignal / beslutningspunkt<textarea data-field="trigger" rows="2" maxlength="600">${esc(r.trigger)}</textarea></label>${sourceSelect(sources,r.sourceId)}</fieldset>`}
function renderRisks(t){const summary=riskSummary(t);$('risk-summary').innerHTML=`<span class="risk-pill ${summary.blocked?'risk-blocked':''}">Blokkerte avhengigheter: ${summary.blocked}</span><span class="risk-pill ${summary.severe?'risk-attention':''}">Åpne risikoer med høy konsekvens: ${summary.severe}</span><span class="risk-pill">Uavklarte avhengigheter: ${summary.unconfirmed}</span>`;
 const priority=r=>r.status==='blocked'?100:riskIsActive(r)?({high:30,medium:20,low:10}[r.severity]):0;
 $('risk-list').innerHTML=t.risks?.length?[...t.risks].sort((a,b)=>priority(b)-priority(a)).map(r=>`<article class="risk-entry ${r.status==='blocked'?'blocked-entry':''} ${!riskIsActive(r)?'resolved-entry':''}"><div class="risk-entry-head"><span class="badge neutral">${riskTypes[r.kind]}</span><span class="risk-pill ${r.status==='blocked'?'risk-blocked':''}">${riskStatuses[r.kind][r.status]}</span></div><h3>${esc(r.title)}</h3><div class="risk-facts"><span>Konsekvens: <strong>${riskLevels[r.severity]}</strong></span>${r.kind==='risk'?`<span>Sannsynlighet: <strong>${riskLevels[r.probability]}</strong></span>`:''}<span>Ansvarlig: <strong>${esc(r.owner||'Ikke avklart')}</strong></span></div><p class="risk-consequence">${esc(r.consequence)}</p><dl><div><dt>Håndtering</dt><dd>${esc(r.action||'Ikke beskrevet')}</dd></div><div><dt>Varselsignal / beslutningspunkt</dt><dd>${esc(r.trigger||'Ikke beskrevet')}</dd></div></dl><p>${sourceReference(t,r.sourceId)}</p></article>`).join(''):'<p class="resource-note">Ingen risikoer eller avhengigheter er registrert for tiltaket. Dette er ikke en vurdering av at risikoen er lav.</p>';
}
